import React, { useState } from 'react';

const PaymentModal = ({ course, onClose }) => {
  const [method, setMethod] = useState('');
  const [processing, setProcessing] = useState(false);
  const [success, setSuccess] = useState(false);

  if (!course) return null;

  const handlePayment = (e) => {
    e.preventDefault();
    setProcessing(true);
    setTimeout(() => {
      setProcessing(false);
      setSuccess(true);
    }, 2000);
  };

  return (
    <div className="fixed inset-0 bg-[#0A0E1A]/90 backdrop-blur-sm flex items-center justify-center z-50 p-4">
      <div className="bg-slate-900/90 border border-slate-800 rounded-2xl p-7 w-full max-w-sm relative">
        <button onClick={onClose} className="absolute top-4 right-4 text-slate-500 hover:text-white text-sm transition-colors">
          ✕
        </button>

        {!success ? (
          <>
            <h2 className="text-white font-bold text-lg mb-1">{course.title}</h2>
            <p className="text-blue-400 font-bold text-xl mb-6">{course.price.toLocaleString()} FCFA</p>

            <form onSubmit={handlePayment} className="space-y-5">
              <div className="grid grid-cols-2 gap-3">
                {['MTN', 'Wave', 'Carte', 'PayPal'].map((m) => (
                  <button
                    key={m}
                    type="button"
                    onClick={() => setMethod(m)}
                    className={`py-3 rounded-lg text-xs font-semibold uppercase tracking-wide border transition-colors ${
                      method === m
                        ? 'border-blue-500 bg-blue-500/10 text-blue-400'
                        : 'border-slate-700 text-slate-400 hover:border-slate-500'
                    }`}
                  >
                    {m}
                  </button>
                ))}
              </div>

              <button
                type="submit"
                disabled={!method || processing}
                className="w-full bg-blue-600 hover:bg-blue-500 disabled:bg-slate-800 disabled:text-slate-600 text-white font-semibold py-3 rounded-lg text-sm transition-colors"
              >
                {processing ? 'Traitement en cours...' : 'Confirmer le paiement'}
              </button>
            </form>
          </>
        ) : (
          <div className="text-center py-6">
            <div className="w-14 h-14 rounded-full bg-emerald-500/10 border border-emerald-500/30 flex items-center justify-center text-emerald-400 text-2xl mx-auto mb-4">✓</div>
            <h3 className="text-white font-bold mb-1">Accès débloqué</h3>
            <p className="text-slate-400 text-sm">Le module est maintenant disponible dans ton espace.</p>
            <button onClick={onClose} className="w-full bg-slate-800 hover:bg-slate-700 text-white font-semibold py-3 rounded-lg text-sm mt-6 transition-colors">
              Fermer
            </button>
          </div>
        )}
      </div>
    </div>
  );
};
export default PaymentModal;
